291     invariant HasMajority(a, lo, up, k) // (2) k has majority among a[lo..up] (in the current window)
292     invariant c == Count(a, lo, up, k) // (3)
293   {
294     if a[up] == k {
295       // One more occurrence of k
296       up, c := up + 1, c + 1;
297     } else if 2 * c > up + 1 - lo {
298       // An occurrence of another value, but k still has the majority
299       up := up + 1;
300     } else {
301       // An occurrence of another value and k just lost the majority.
302       // Prove that k has exactly 50% in the future window a[lo..up + 1]:
303       calc /* k has 50% among a[lo..up + 1] */ {
304         true;
305       ==  // negation of the previous branch condition
306         2 * c <= up + 1 - lo;
307       ==  // loop invariant (3)
308         2 * Count(a, lo, up, k) <= up + 1 - lo;
