310             true;
311           ==  // loop invariant (2)
312             HasMajority(a, lo, up, k);
313           ==  // def. HasMajority
314             2 * Count(a, lo, up, k) > up - lo;
315           ==
316             2 * Count(a, lo, up, k) >= up + 1 - lo;
317           }
318         2 * Count(a, lo, up, k) == up + 1 - lo;
319       }
320       up := up + 1;
321       assert 2 * Count(a, lo, up, k) == up - lo; // k has exactly 50% in the current window a[lo..up]
322 
323       // We are going to start a new window a[up..up + 1] and choose a new candidate,
324       // so invariants (2) and (3) will be easy to re-establish.
325       // To re-establish (1) we have to prove that K has majority among a[up..], as up will become the new lo.
326       // The main idea is that we had enough K's in a[lo..], and there cannot be too many in a[lo..up].
327       calc /* K has majority among a[up..] */ {
328         true;
329       ==  // loop invariant (1)
330         HasMajority(a, lo, |a|, K);
331       ==
332         2 * Count(a, lo, |a|, K) > |a| - lo;
333       ==  { Lemma_Split(a, lo, up, |a|, K); }
