338               2 * Count(a, lo, up, K);
339             ==
340               2 * Count(a, lo, up, k);
341             ==  { assert 2 * Count(a, lo, up, k) == up - lo; } // k has 50% among a[lo..up]
342               up - lo;
343             }
344           } else {
345             calc {
346               true;
347             ==  { Lemma_Unique(a, lo, up, k, K); }
348               Count(a, lo, up, K) + Count(a, lo, up, k) <= up - lo;
349             ==
350               2 * Count(a, lo, up, K) + 2 * Count(a, lo, up, k) <= 2 * (up - lo);
351             ==  { assert 2 * Count(a, lo, up, k) == up - lo; } // k has 50% among a[lo..up]
352               2 * Count(a, lo, up, K) <= up - lo;
353             }
354           }
355           assert 2 * Count(a, lo, up, K) <= up - lo;
356         }
357         // subtract off Count(a, lo, up, K) from the LHS and subtract off the larger amount up - lo from the RHS
358         2 * Count(a, up, |a|, K) > (|a| - lo) - (up - lo);
359       ==
