361       ==
362         HasMajority(a, up, |a|, K);
363       }
364       k, lo, up, c := a[up], up, up + 1, 1;
365       assert HasMajority(a, lo, |a|, K);
366     }
367   }
368   Lemma_Unique(a, lo, |a|, K, k);  // both k and K have a majority among a[lo..], so K == k
